local({
  items <- cbind(as.numeric(cts_spanked), as.numeric(cts_hit_object), as.numeric(cts_slapped))
  pcg <- case_when(
    rowSums(items > 0, na.rm = TRUE) > 0 ~ "TRUE",
    rowSums(!is.na(items)) > 0 ~ "FALSE",
    .default = NA_character_
  )
  case_when(
    wave == "Year 15" ~ recode_values(as.numeric(youth_pcg_hit_slapped), 1 ~ "FALSE", c(2, 3) ~ "TRUE"),
    .default = pcg
  )
})

local({
  r <- cbind(as.numeric(teacher_rating_literacy), as.numeric(teacher_rating_science), as.numeric(teacher_rating_maths))
  r <- ifelse(r >= 1 & r <= 5, r, NA_real_)
  recode_values(ceiling(rowMeans(r) - 0.5), 5 ~ "Very good", 4 ~ "Good", 3 ~ "Average", c(1, 2) ~ "Below average")
})

local({
  nights <- pmax(sleep_trouble_falling_nights, sleep_trouble_staying_nights, na.rm = TRUE)
  case_when(
    nights == 0 ~ "Never",
    nights <= 2 ~ "Sometimes",
    nights <= 4 ~ "Often",
    nights <= 7 ~ "Always",
    .default = NA_character_
  )
})

local({
  measured <- !is.na(as.numeric(child_weight_kg) / as.numeric(child_height_cm))
  reported <- !is.na(as.numeric(youth_weight_lb) / (as.numeric(youth_height_ft) * 12 + as.numeric(youth_height_in)))
  case_when(
    measured & (as.numeric(child_weight_source) %in% 2 | as.numeric(child_height_source) %in% 3) ~ "Unknown",
    measured ~ "Measured",
    reported ~ "Self-reported",
    .default = NA_character_
  )
})

local({
  pds <- "Pubertal Development Scale (parent), 5 of 5 items, 1-4 item scoring (range 1-4), mean; boys growth spurt, body hair, skin, voice, facial hair; girls growth spurt, body hair, skin, breasts, menarche (no 1, yes 4); complete cases"
  menarche <- "Menarche (self), 1 item, 0-1 item scoring (range 0-1), menarche indicator; girls only"
  case_when(wave == "Year 9" ~ pds, wave == "Year 15" ~ menarche, .default = NA_character_)
})
